            p = as_pos(v)
            if p is not None:
                return p
        return None

    def extract_positions(v):
        out = []
        if v is None:
            return out
        if isinstance(v, dict):
            p = as_pos(v)
            if p is not None:
                out.append(p)
            else:
                for item in v.values():
                    out.extend(extract_positions(item))
        elif isinstance(v, (list, tuple)):
