    for k in ("resources", "resource_tiles", "resource_positions", "foods", "food", "coins", "targets", "collectibles"):
        resources.extend(extract_positions(get(observation, k)))

    enemies = []
    for k in ("enemies", "enemy_positions", "opponents", "players", "predators", "chasers"):
