    goals = []
    for k in ("goals", "goal_positions", "bases", "home", "home_base", "territory_targets", "capture_points"):
        goals.extend(extract_positions(get(observation, k)))

    neutral = []
    for k in ("neutral", "unclaimed", "frontier", "border", "empty_targets", "territory"):
        neutral.extend(extract_positions(get(observation, k)))

